<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class SocialTeacherController extends Controller{
 private function access(Request $r){$u=$r->user();abort_unless($u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('social_teacher')||$u->canDo('socialwork.view'),403);}
 public function index(Request $r){$this->access($r);$active=DB::table('students')->where('status','active');$stats=['students'=>$active->count(),'passports'=>DB::table('student_social_passports')->count(),'statuses'=>DB::table('student_social_statuses')->where('status','active')->count(),'supports'=>DB::table('student_social_supports')->where('status','active')->count(),'followups'=>DB::table('student_social_followups')->where('status','active')->count()];$groups=DB::table('study_groups')->where('active',1)->orderBy('name')->get();$activities=DB::table('social_teacher_activities as a')->leftJoin('study_groups as g','g.id','=','a.study_group_id')->leftJoin('students as s','s.id','=','a.student_id')->select('a.*','g.name as group_name','s.last_name','s.first_name')->orderByDesc('a.planned_on')->limit(30)->get();return view('social-teacher.index',compact('stats','groups','activities'));}
 public function students(Request $r){$this->access($r);$q=DB::table('students as s')->leftJoin('study_groups as g','g.id','=','s.current_group_id')->leftJoin('student_social_passports as p','p.student_id','=','s.id')->where('s.status','active')->select('s.id','s.last_name','s.first_name','s.middle_name','g.name as group_name','p.id as passport_id','p.low_income','p.large_family','p.orphan','p.guardianship','p.disabled','p.ovz','p.risk_group','p.dormitory');if($r->filled('group'))$q->where('s.current_group_id',$r->integer('group'));if($r->filled('q')){$term='%'.$r->q.'%';$q->where(fn($z)=>$z->where('s.last_name','like',$term)->orWhere('s.first_name','like',$term));}$rows=$q->orderBy('s.last_name')->get();$groups=DB::table('study_groups')->where('active',1)->orderBy('name')->get();return view('social-teacher.students',compact('rows','groups'));}
 public function activityStore(Request $r){$this->access($r);$d=$r->validate(['planned_on'=>'required|date','activity_type'=>'required|string|max:120','title'=>'required|string|max:255','study_group_id'=>'nullable|exists:study_groups,id','student_id'=>'nullable|exists:students,id','duration_minutes'=>'nullable|integer|min:1|max:1440','content'=>'nullable|string|max:10000']);DB::table('social_teacher_activities')->insert($d+['status'=>'planned','user_id'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Мероприятие добавлено в план');}
 public function activityUpdate(Request $r,$id){$this->access($r);$d=$r->validate(['planned_on'=>'required|date','activity_type'=>'required|string|max:120','title'=>'required|string|max:255','status'=>'required|in:planned,in_progress,completed,cancelled','duration_minutes'=>'nullable|integer|min:1|max:1440','content'=>'nullable|string|max:10000','result'=>'nullable|string|max:10000']);$d['completed_on']=$d['status']==='completed'?now()->toDateString():null;DB::table('social_teacher_activities')->where('id',$id)->update($d+['updated_at'=>now()]);return back()->with('success','Запись обновлена');}
 public function activityDelete(Request $r,$id){$this->access($r);DB::table('social_teacher_activities')->where('id',$id)->delete();return back()->with('success','Запись удалена');}
 public function report(Request $r){$this->access($r);$from=$r->input('from',now()->startOfMonth()->toDateString());$to=$r->input('to',now()->toDateString());$activities=DB::table('social_teacher_activities')->whereBetween('planned_on',[$from,$to])->select('activity_type',DB::raw('COUNT(*) cnt'),DB::raw('COALESCE(SUM(duration_minutes),0) minutes'))->groupBy('activity_type')->orderByDesc('cnt')->get();$supports=DB::table('student_social_supports')->whereBetween('created_at',[$from.' 00:00:00',$to.' 23:59:59'])->count();$followups=DB::table('student_social_followups')->whereBetween('started_on',[$from,$to])->count();$closed=DB::table('student_social_followups')->whereBetween('ended_on',[$from,$to])->count();return view('social-teacher.report',compact('from','to','activities','supports','followups','closed'));}
}